-- Dumping structure for table esto_portfolio.project_investigators
CREATE TABLE IF NOT EXISTS `project_investigators` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_xref_id` int DEFAULT NULL,
  `project_id` int NOT NULL,
  `investigator_id` int NOT NULL,
  `role` enum('PRINCIPAL','CO_INVESTIGATOR') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PRINCIPAL',
  `organization_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `project_investigators_source_xref_id_key` (`source_xref_id`),
  KEY `project_investigators_project_id_idx` (`project_id`),
  KEY `project_investigators_investigator_id_idx` (`investigator_id`),
  KEY `project_investigators_organization_id_idx` (`organization_id`),
  CONSTRAINT `project_investigators_investigator_id_fkey` FOREIGN KEY (`investigator_id`) REFERENCES `investigators` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `project_investigators_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `project_investigators_project_id_fkey` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6218 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

