-- Dumping structure for table esto_portfolio.project_tech_categories
CREATE TABLE IF NOT EXISTS `project_tech_categories` (
  `project_id` int NOT NULL,
  `category_id` int NOT NULL,
  PRIMARY KEY (`project_id`,`category_id`),
  KEY `project_tech_categories_category_id_idx` (`category_id`),
  CONSTRAINT `project_tech_categories_category_id_fkey` FOREIGN KEY (`category_id`) REFERENCES `tech_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `project_tech_categories_project_id_fkey` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

