-- Dumping structure for table esto_portfolio.projects
CREATE TABLE IF NOT EXISTS `projects` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source_internal_id` int DEFAULT NULL,
  `program_flag` enum('ESTO','OTHER') COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_code` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `abstract` text COLLATE utf8mb4_unicode_ci,
  `completed` tinyint(1) NOT NULL DEFAULT '0',
  `status_text` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completion_fy` int DEFAULT NULL,
  `trl_in` int DEFAULT NULL,
  `trl_current` int DEFAULT NULL,
  `trl_out` int DEFAULT NULL,
  `quad_chart_url` text COLLATE utf8mb4_unicode_ci,
  `pi_id` int DEFAULT NULL,
  `organization_id` int DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  `program_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `budget_code` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `project_abbrev` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `year_valid` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `projects_source_internal_id_key` (`source_internal_id`),
  KEY `projects_program_flag_idx` (`program_flag`),
  KEY `projects_completed_idx` (`completed`),
  KEY `projects_pi_id_idx` (`pi_id`),
  KEY `projects_organization_id_idx` (`organization_id`),
  FULLTEXT KEY `projects_title_abstract_idx` (`title`,`abstract`),
  CONSTRAINT `projects_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `projects_pi_id_fkey` FOREIGN KEY (`pi_id`) REFERENCES `investigators` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1002 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

